<?php use App\Core\{Auth,Csrf};?><?php if(Auth::can('inventory.manage')):?><section class="panel"><h2>Phiếu nhập / xuất kho</h2><form action="/admin/inventory" method="post" class="row g-3"><?= Csrf::field() ?><input type="hidden" name="request_token" value="<?= bin2hex(random_bytes(32)) ?>"><div class="col-md-4"><label class="form-label" for="stock-product">Sản phẩm</label><select class="form-select" id="stock-product" name="product_id"><?php foreach($products as $p):?><option value="<?= $p['id'] ?>"><?= e($p['sku'].' · '.$p['name']) ?></option><?php endforeach?></select></div><div class="col-md-2"><label class="form-label" for="stock-type">Loại phiếu</label><select class="form-select" id="stock-type" name="type"><option value="receipt">Nhập kho</option><option value="issue">Xuất kho</option></select></div><div class="col-md-2"><label class="form-label" for="stock-qty">Số lượng</label><input class="form-control" id="stock-qty" name="quantity" type="number" min="1" required></div><div class="col-md-4"><label class="form-label" for="stock-reason">Lý do</label><input class="form-control" id="stock-reason" name="reason" minlength="5" maxlength="500" required></div><div><button id="stock-submit" type="submit" class="btn btn-primary">Lưu phiếu kho</button></div></form></section><?php endif?><section class="panel table-wrap"><h2>Tồn kho hiện tại</h2><table class="table"><thead><tr><th>SKU</th><th>Sản phẩm</th><th>Tồn</th><th>Ngưỡng tối thiểu</th><th>Cảnh báo</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?= e($p['sku']) ?></td><td><?= e($p['name']) ?></td><td><b><?= $p['stock'] ?></b></td><td><?= $p['min_stock'] ?></td><td><?= $p['stock']<=$p['min_stock']?'<span class="status cancelled">Cần nhập thêm</span>':'<span class="status completed">Đủ tồn</span>' ?></td></tr><?php endforeach?></tbody></table></section><section class="panel table-wrap"><h2>200 biến động gần nhất</h2><table class="table"><thead><tr><th>Thời gian</th><th>Sản phẩm</th><th>Loại</th><th>Biến động</th><th>Tồn sau</th><th>Lý do / Người thực hiện</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?= e($m['created_at']) ?></td><td><?= e($m['product_name']) ?></td><td><?= e(status_label($m['type'])) ?></td><td><?= $m['quantity']>0?'+':'' ?><?= $m['quantity'] ?></td><td><?= $m['stock_after'] ?></td><td><?= e($m['reason']) ?><small class="d-block muted"><?= e($m['actor']??'Hệ thống') ?></small></td></tr><?php endforeach?></tbody></table></section>
